type WorldState = Record<string, string>;

const initialState: WorldState = {
  Fen: "pex",
};

const failure = (error: string): { success: false; error: string } => ({
  success: false,
  error,
});

export const protocol: WorldProtocol<WorldState> = {
  reset(): WorldState {
    return { ...initialState };
  },

  applyOperation(state: WorldState, operationDisplayName: string) {
    const fenState = state.Fen;

    if (operationDisplayName === "advanceFen") {
      if (fenState !== "pex") {
        return failure("advanceFen requires Fen to be pex");
      }

      return {
        success: true,
        newState: { ...state, Fen: "dor" },
      };
    }

    if (operationDisplayName === "recoverFen") {
      if (fenState !== "dor") {
        return failure("recoverFen requires Fen to be dor");
      }

      return {
        success: true,
        newState: { ...state, Fen: "pex" },
      };
    }

    return failure(`Unknown operation: ${operationDisplayName}`);
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return { ...state };
  },
};
